import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        m = int(input[index + 1])
        index += 2
        sets = []
        for _ in range(m):
            vi = int(input[index])
            s = set(map(int, input[index + 1:index + 1 + vi]))
            sets.append(s)
            index += 1 + vi
        graph = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n):
                if all((i not in s and j not in s) or (i in s and j in s) for s in sets):
                    graph[i].append(j)
                    graph[j].append(i)
        visited = [False] * n
        def dfs(node, color):
            stack = [(node, color)]
            while stack:
                node, color = stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append((neighbor, 1 - color))
        colors = [-1] * n
        for i in range(n):
            if not visited[i]:
                dfs(i, 0)
        results.append(max(colors) + 1)
    print('\n'.join(map(str, results)))

main()
